import { createHmac, timingSafeEqual, type KeyObject } from 'node:crypto';
import { encodeContext, hkdfKey } from './primitives.js';

/**
 * The key pin of F-030 (S2c review P2-2): an HMAC under a deployment secret that is **not** in the database
 * (`FLUX_KEY_PIN_SECRET`, generated by `./flux` like the keyring token and given to the API and the worker only). It
 * covers every holder row's identity and public key and every key version's check value and commitment, written by
 * the server's own paths (creation, a password, a recovery code, a rotation's start) and verified at every unlock and
 * before any DEK is sealed to a holder. So someone who can only write to the database can neither plant a holder
 * (a rogue recovery holder while locked included) nor mint a key version a holder would accept. It does not stop
 * someone who also holds the server's environment (the same trust the keyring token carries).
 */
const LABEL = { key: 'flux key pin v1', holder: 'flux pin holder v1', version: 'flux pin version v1' } as const;

export interface PinnedHolder { workspaceId: string; holderId: string; kind: 'password' | 'recovery'; userId: string | null; publicKey: string }
export interface PinnedVersion { workspaceId: string; keyVersion: number; checkValue: string; commitment: string | null }

const same = (given: unknown, expected: string) => {
  if (typeof given !== 'string') return false;
  const a = Buffer.from(given); const b = Buffer.from(expected);
  return a.length === b.length && timingSafeEqual(a, b);
};

export class KeyPin {
  private constructor(private readonly key: KeyObject) {}

  /** At least 32 characters (the generated value is 32 random bytes, base64url). */
  static fromSecret(secret: string): KeyPin {
    if (secret.length < 32) throw new Error('FLUX_KEY_PIN_SECRET must be at least 32 characters');
    return new KeyPin(hkdfKey(Buffer.from(secret, 'utf8'), Buffer.alloc(0), encodeContext([LABEL.key])));
  }

  private mac(parts: (string | number)[]) {
    return createHmac('sha256', this.key).update(encodeContext(parts)).digest('base64url');
  }

  holder(h: PinnedHolder): string {
    return this.mac([LABEL.holder, h.workspaceId, h.holderId, h.kind, h.userId ?? '', h.publicKey]);
  }
  holderValid(h: PinnedHolder, pin: unknown): boolean { return same(pin, this.holder(h)); }

  version(v: PinnedVersion): string {
    return this.mac([LABEL.version, v.workspaceId, v.keyVersion, v.checkValue, v.commitment ?? '']);
  }
  versionValid(v: PinnedVersion, pin: unknown): boolean { return same(pin, this.version(v)); }
}

/** The pin of this process, or null when `FLUX_KEY_PIN_SECRET` is not set (encrypted spaces then cannot be opened). */
export function keyPinFromEnv(env: Readonly<Record<string, string | undefined>>): KeyPin | null {
  const secret = env.FLUX_KEY_PIN_SECRET?.trim();
  return secret ? KeyPin.fromSecret(secret) : null;
}
